"""The fixed verification call script. Nothing here is generated by an LLM.

It discloses that the call is automated and on whose behalf, says whether it is recorded
(only with recording consent), asks whether the vendor sent the change request, asks for a
read-back of the last characters of the new details and the speaker's name, and never reads
a full account number aloud."""
import cases


def readback_steps(case):
    """The read-back questions: the confirmation code, plus the bank code ending when both an
    account and a bank code changed. Returns [(step, question, expected)]."""
    fields = {c["field"]: c["new"] for c in case["changes"]}
    steps = [("readback_code", "Please read me %s." % cases.confirm_label(case), cases.confirm_code(case))]
    if "acct_last4" in fields:
        for f, label in (("ifsc", "the new IFSC"), ("iban", "the new IBAN")):
            if fields.get(f):
                steps.append(("readback_bank", "Please read me the last 4 characters of %s." % label,
                              fields[f][-4:].upper()))
                break
    return steps


def build_script(case, vendor, business_name=None, recording=False):
    """Ordered prompts for the call. Each step names the answer it expects."""
    on_behalf = business_name or "one of your customers"
    who = vendor.get("contact") or "someone at %s" % vendor["name"]
    opening = ("Hello. This is an automated call on behalf of %s, about a request to change your "
               "bank details. %s" % (on_behalf, "This call is recorded and transcribed, as you agreed."
                                     if recording else "This call is not recorded."))
    steps = [
        {"step": "opening", "say": opening},
        {"step": "sent", "say": "We received a request to change your bank details. Did %s send it? "
                                "Please say yes or no." % who},
    ]
    for step, question, expected in readback_steps(case):
        # "expect" is never spoken: it's what the answer is compared with afterwards
        steps.append({"step": step, "say": question, "if": "yes", "expect": expected})
    steps.append({"step": "name", "say": "Please tell me your name.", "if": "yes"})
    steps.append({"step": "denied", "say": "Please confirm that you did not send this request.", "if": "no"})
    steps.append({"step": "closing", "say": "Thank you. Nothing will change until %s confirms it "
                                            "personally. Goodbye." % on_behalf})
    return steps


def spoken_text(script):
    return " ".join(s["say"] for s in script)
